from pynwb import NWBHDF5IO
import numpy as np
path='/app/data/sub-m12/sub-m12_ses-01_behavior+ophys.nwb'
with NWBHDF5IO(path,'r',load_namespaces=True) as io:
    nwb=io.read()
    beh = nwb.processing['behavior'].data_interfaces['BehavioralTimeSeries'].time_series
    data = {k: np.asarray(beh[k].data[:]) for k in ['trial number','teleport','trial_start','position','reward_zone','environment','autoreward','lick','speed']}
    tr = data['trial number'].astype(int)
    valid_trials = np.unique(tr[tr>=0])
    summaries=[]
    for t in [0,1,28,29,30,31,58,59,60,61,78,79]:
        if t not in valid_trials: continue
        mask = tr==t
        pos = data['position'][mask]
        rz = data['reward_zone'][mask]
        rz_pos = pos[rz>0]
        env = np.unique(data['environment'][mask])
        summaries.append({
            'trial':int(t),
            'nframes':int(mask.sum()),
            'startsum':int(data['trial_start'][mask].sum()),
            'telesum':int(data['teleport'][mask].sum()),
            'env':env.tolist(),
            'rz_vals':np.unique(rz).tolist(),
            'rz_count':int((rz>0).sum()),
            'rz_min':None if rz_pos.size==0 else float(np.min(rz_pos)),
            'rz_max':None if rz_pos.size==0 else float(np.max(rz_pos)),
            'any_lick':int((data['lick'][mask]>0).any()),
            'max_lick':float(np.max(data['lick'][mask])),
            'max_speed':float(np.max(data['speed'][mask])),
            'autoreward_any':int((data['autoreward'][mask]>0).any()),
        })
    for s in summaries:
        print(s)
